SELECT sm.sm_ship_mode_id, sm.sm_type, d.d_year, COUNT(*) AS return_count, SUM(cr.cr_return_amount) AS total_return_amount, MAX(cr.cr_return_tax) AS max_return_tax, CASE WHEN SUM(cr.cr_return_amount) > 20000 THEN 'Very High' WHEN SUM(cr.cr_return_amount) BETWEEN 10000 AND 20000 THEN 'High' ELSE 'Normal' END AS amount_category FROM catalog_returns cr JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk WHERE d.d_year BETWEEN 2015 AND 2020 GROUP BY sm.sm_ship_mode_id, sm.sm_type, d.d_year HAVING COUNT(*) > 50 ORDER BY total_return_amount DESC
